:root {
  --bg: #fafafa;
  --surface: #ffffff;
  --surface-subtle: #f4f4f5;
  --text: #171717;
  --text-secondary: #525252;
  --muted: #737373;
  --border: rgba(23, 23, 23, 0.08);
  --border-strong: rgba(23, 23, 23, 0.16);
  --primary: #ea580c;
  --primary-hover: #c2410c;
  --primary-soft: #fff7ed;
  --primary-border: rgba(234, 88, 12, 0.24);
  --shadow-sm: 0 1px 2px rgba(23, 23, 23, 0.05);
  --shadow-md: 0 8px 24px rgba(23, 23, 23, 0.06);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  font-weight: 400;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}

/* --- AUTHENTIFICATION --- */
.auth-shell {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: var(--bg);
}

.auth-card {
  width: 100%;
  max-width: 420px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-md);
}

.auth-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}

.auth-logo {
  height: 44px;
  width: auto;
  object-fit: contain;
}

.auth-brand h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.25;
  font-weight: 500;
  color: var(--text);
}

.auth-brand p {
  margin: 4px 0 0;
  font-size: 13px;
  font-weight: 400;
  color: var(--muted);
}

.auth-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--surface-subtle);
  padding: 4px;
  border-radius: var(--radius-sm);
  margin-bottom: 16px;
}

.auth-tab {
  border: none;
  background: transparent;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 6px;
  cursor: pointer;
  transition: color 150ms var(--ease), background-color 150ms var(--ease);
}

.auth-tab.active {
  background: var(--surface);
  color: var(--text);
  box-shadow: var(--shadow-sm);
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.auth-feedback {
  font-size: 13px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}
.auth-feedback.error {
  background: #fef2f2;
  color: #b91c1c;
  border: 1px solid rgba(185, 28, 28, 0.2);
}
.auth-feedback.success {
  background: #f0fdf4;
  color: #15803d;
  border: 1px solid rgba(21, 128, 61, 0.2);
}

/* --- TOPBAR --- */
.topbar {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.topbar-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo-img {
  height: 36px;
  width: auto;
  object-fit: contain;
  display: block;
}

.brand strong {
  color: var(--text);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.2;
}

.brand small {
  display: block;
  color: var(--muted);
  font-weight: 400;
  font-size: 12px;
  line-height: 1.35;
}

.nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.nav a {
  text-decoration: none;
  color: var(--text-secondary);
  font-weight: 500;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  transition: color 150ms var(--ease), background-color 150ms var(--ease);
}

.nav a.active {
  background: var(--primary-soft);
  color: var(--primary);
}

.nav a:hover:not(.active) {
  background: var(--surface-subtle);
  color: var(--text);
}

.user-menu {
  display: flex;
  align-items: center;
  gap: 8px;
}

.user-pill {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--surface-subtle);
  padding: 4px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
}

/* --- LAYOUT & EN-TÊTE --- */
.wrap {
  max-width: 1240px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.page-header h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.2;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--text);
}

.page-header p {
  margin: 4px 0 0;
  font-size: 14px;
  font-weight: 400;
  color: var(--text-secondary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.toast-banner {
  background: var(--primary-soft);
  border: 1px solid var(--primary-border);
  color: var(--primary-hover);
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 500;
}

.layout {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 20px;
  align-items: stretch;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.card-head h2 {
  margin: 0;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 500;
  color: var(--text);
}

.card-subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--muted);
}

.muted-count {
  font-size: 12px;
  font-weight: 500;
  color: var(--muted);
  background: var(--surface-subtle);
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--border);
}

.badge-info {
  background: var(--surface-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--border);
  font-weight: 500;
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 6px;
}

.hint-text {
  font-size: 12px;
  color: var(--muted);
  font-weight: 400;
}

/* --- CALENDRIER --- */
.cal-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
}

table.cal {
  width: 100%;
  height: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--border);
}

table.cal th {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--surface-subtle);
  padding: 8px 4px;
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
}

table.cal td {
  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  height: 88px;
  vertical-align: top;
  padding: 4px;
  background: var(--surface);
  transition: background-color 140ms var(--ease);
}

table.cal td.blank {
  background: var(--surface-subtle);
}

table.cal td.active-range {
  background: var(--primary-soft);
  box-shadow: inset 0 2px 0 var(--primary);
}

.dnum {
  font-size: 12px;
  font-weight: 500;
  margin-bottom: 4px;
  color: var(--text-secondary);
}

.mark {
  width: 100%;
  border: none;
  border-radius: 4px;

:root {
  --bg-page: #fafafa;
  --bg-surface: #ffffff;
  --bg-surface-subtle: #f4f4f5;
  --bg-surface-hover: #ececef;
  --text-primary: #171717;
  --text-secondary: #525252;
  --text-muted: #737373;
  --border-color: rgba(23, 23, 23, 0.08);
  --border-strong: rgba(23, 23, 23, 0.16);
  --accent-primary: #1d4ed8;
  --accent-primary-hover: #1e40af;
  --accent-soft: rgba(29, 78, 216, 0.08);
  --status-todo-bg: #f4f4f5;
  --status-todo-fg: #3f3f46;
  --status-doing-bg: #fef3c7;
  --status-doing-fg: #92400e;
  --status-done-bg: #dcfce7;
  --status-done-fg: #166534;
  --shadow-sm: 0 1px 2px rgba(23, 23, 23, 0.05);
  --shadow-md: 0 8px 24px rgba(23, 23, 23, 0.06);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

html[data-theme="dark"] {
  --bg-page: #141415;
  --bg-surface: #19191b;
  --bg-surface-subtle: #232325;
  --bg-surface-hover: #2c2c2f;
  --text-primary: #ededed;
  --text-secondary: #a1a1a6;
  --text-muted: #85858b;
  --border-color: rgba(237, 237, 237, 0.08);
  --border-strong: rgba(237, 237, 237, 0.16);
  --accent-primary: #3b82f6;
  --accent-primary-hover: #2563eb;
  --accent-soft: rgba(59, 130, 246, 0.14);
  --status-todo-bg: #232325;
  --status-todo-fg: #d4d4d8;
  --status-doing-bg: rgba(245, 158, 11, 0.18);
  --status-doing-fg: #fcd34d;
  --status-done-bg: rgba(34, 197, 94, 0.18);
  --status-done-fg: #86efac;
  --shadow-sm: none;
  --shadow-md: none;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: "Inter", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 14px;
  font-weight: 400;
  background-color: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
  transition: background-color 180ms var(--ease), color 180ms var(--ease);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 30;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
}

.header-inner {
  max-width: 1360px;
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--text-primary);
}

.brand-mark {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background-color: var(--accent-primary);
  color: #ffffff;
  font-weight: 500;
  font-size: 14px;
  display: grid;
  place-items: center;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-text strong {
  font-size: 16px;
  font-weight: 500;
  line-height: 1.2;
}

.brand-text small {
  font-size: 12px;
  color: var(--text-muted);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

.nav-link {
  text-decoration: none;
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 14px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  transition: background-color 150ms var(--ease), color 150ms var(--ease);
}

.nav-link:hover {
  background-color: var(--bg-surface-hover);
  color: var(--text-primary);
}

.nav-link.active {
  background-color: var(--accent-soft);
  color: var(--accent-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius-sm);
  padding: 8px 16px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 150ms var(--ease), color 150ms var(--ease), border-color 150ms var(--ease), transform 120ms var(--ease);
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--accent-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--accent-primary-hover);
}

.btn-secondary {
  background-color: var(--bg-surface-subtle);
  color: var(--text-primary);
  border-color: var(--border-strong);
}

.btn-secondary:hover {
  background-color: var(--bg-surface-hover);
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-primary);
  border-color: var(--border-color);
}

.btn-ghost:hover {
  background-color: var(--bg-surface-hover);
}

.btn-danger-outline {
  background-color: transparent;
  color: #dc2626;
  border-color: rgba(220, 38, 38, 0.32);
}

.btn-danger-outline:hover {
  background-color: rgba(220, 38, 38, 0.08);
}

.page-container {
  max-width: 1360px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.page-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.eyebrow {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  color: var(--accent-primary);
  margin-bottom: 4px;
}

.page-hero h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.15;
  font-weight: 500;
  letter-spacing: -0.02em;
}

.hero-subtitle {
  margin: 8px 0 0;
  color: var(--text-secondary);
  max-width: 680px;
  font-size: 14px;
}

.period-toolbar {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  flex-wrap: wrap;
  background-color: var(--bg-surface);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.toolbar-field, .field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.toolbar-field select, .toolbar-field input, .field input, .field select {
  font-family: inherit;
  font-size: 14px;
  color: var(--text-primary);
  background-color: var(--bg-surface-subtle);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  min-width: 112px;
}

.toolbar-field select:focus, .toolbar-field input:focus, .field input:focus, .field select:focus {
  outline: 2px solid var(--accent-primary);
  outline-offset: 1px;
  border-color: var(--accent-primary);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.kpi-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.kpi-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
}

.kpi-value {
  font-size: 28px;
  font-weight: 500;
  line-height: 1.1;
  color: var(--text-primary);
}

.kpi-value-sm {
  font-size: 20px;
  line-height: 1.25;
}

.kpi-meta {
  font-size: 13px;
  color: var(--text-secondary);
}

.progress-track {
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background-color: var(--bg-surface-hover);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background-color: var(--accent-primary);
  border-radius: 4px;
  transition: width 220ms var(--ease);
}

.workspace-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(340px, 1fr);
  gap: 20px;
  align-items: start;
}

.panel {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
}

.panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.panel-header h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 500;
}

.panel-desc {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-secondary);
}

.calendar-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.legend-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 8px;
  border-radius: 6px;
  background-color: var(--bg-surface-subtle);
  border: 1px solid var(--border-color);
}

.legend-dot {
